var data = $input.first().json;
var reviews = data.reviews || [];
var count = data.count || 0;

return reviews.map(function(r) {
  return { json: { ...r, total_count: count } };
});

var claudeData = $input.first().json;
var reply = '';
try {
  reply = claudeData.content[0].text.trim();
} catch(e) {
  reply = 'Merci pour votre retour. N\'hésitez pas à nous contacter directement pour en discuter. — L\'équipe acme Intérim';
}

var batchNode = $('⏳ Traiter 1 par 1');
var original = batchNode.first().json;

return [{
  json: {
    nom: original.nom,
    note: original.note,
    commentaire: original.commentaire,
    iso_date: original.iso_date,
    review_link: original.review_link || '',
    total_count: original.total_count,
    reponse_ia: reply
  }
}];

var items = $input.all();
var count = items.length;

var rows = '';
for (var i = 0; i < items.length; i++) {
  var r = items[i].json;
  var bg = (i % 2 === 0) ? '#f9f9f9' : '#ffffff';
  var commentaire = r.commentaire || '-';
  var reponse = r.reponse_ia || '-';

  var noteColor = '#333';
  if (r.note >= 4) noteColor = '#059669';
  else if (r.note >= 3) noteColor = '#d97706';
  else noteColor = '#dc2626';

  var stars = '';
  for (var s = 0; s < 5; s++) {
    stars += s < r.note ? '★' : '☆';
  }

  rows += '<tr style="background-color:' + bg + ';">';
  rows += '<td colspan="3" style="padding:16px 12px 8px;border-top:2px solid #e0e0e0;">';
  rows += '<strong style="font-size:15px;">' + r.nom + '</strong>';
  rows += ' — <span style="color:' + noteColor + ';font-weight:bold;font-size:15px;">' + stars + ' ' + r.note + '/5</span>';
  rows += '</td></tr>';

  rows += '<tr style="background-color:' + bg + ';">';
  rows += '<td colspan="3" style="padding:4px 12px 12px;font-size:14px;color:#333;">';
  rows += '💬 <em>"' + commentaire + '"</em>';
  rows += '</td></tr>';

  rows += '<tr style="background-color:#eef6ff;">';
  rows += '<td colspan="3" style="padding:12px;font-size:14px;border-left:4px solid #0066cc;">';
  rows += '<strong style="color:#0066cc;">🤖 Réponse suggérée par Claude :</strong><br><br>';
  rows += '<span style="color:#333;line-height:1.6;">' + reponse + '</span><br><br>';
  rows += '<span style="font-size:12px;color:#888;">👆 Copie cette réponse et colle-la sur Google Maps → ';
  rows += '<a href="https://www.google.com/maps/place/?q=place_id:ChIJBQiyk2135kcRdCiq5VD7YRs" style="color:#0066cc;">Ouvrir Google Maps</a>';
  rows += '</span>';
  rows += '</td></tr>';

  rows += '<tr><td colspan="3" style="height:8px;"></td></tr>';
}

var html = '<table width="100%" cellpadding="0" cellspacing="0" style="font-family:Arial,sans-serif;max-width:700px;">';
html += '<tr><td style="padding:20px;background:linear-gradient(135deg,#0044aa,#0088ff);border-radius:8px 8px 0 0;">';
html += '<span style="font-size:20px;font-weight:bold;color:#ffffff;">✈️ ' + count + ' nouvel(s) avis Google — acme Intérim</span><br>';
html += '<span style="font-size:13px;color:#cce0ff;">Avis détectés cette semaine • Réponses IA pré-rédigées ci-dessous</span>';
html += '</td></tr>';
html += '<tr><td style="padding:12px 0;">';
html += '<table width="100%" cellpadding="0" cellspacing="0" style="font-family:Arial,sans-serif;max-width:700px;border-collapse:collapse;">';
html += rows;
html += '</table>';
html += '</td></tr>';
html += '<tr><td style="padding:16px;background:#f0f0f0;border-radius:0 0 8px 8px;font-size:12px;color:#666;text-align:center;">';
html += '🔗 <a href="https://www.google.com/maps/place/?q=place_id:ChIJBQiyk2135kcRdCiq5VD7YRs" style="color:#0066cc;">Voir tous les avis sur Google Maps</a>';
html += ' • Les réponses sont générées par IA — vérifie avant de publier !';
html += '</td></tr></table>';

return [{ json: { subject: '✈️ ' + count + ' nouvel(s) avis Google + réponses IA — acme Intérim', body: html } }];

var data = $input.first().json;
var reviews = data.reviews || [];

var now = new Date();
var sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

var staticData = $getWorkflowStaticData('global');
var lastSeenDate = staticData.lastSeenDate || '';

var newReviews = [];

for (var i = 0; i < reviews.length; i++) {
  var r = reviews[i];
  var isoDate = r.iso_date_of_last_edit || r.iso_date || '';
  if (isoDate) {
    var reviewDate = new Date(isoDate);
    if (reviewDate < sevenDaysAgo) { break; }
  }
  if (lastSeenDate && isoDate <= lastSeenDate) { break; }

  var userName = 'Anonyme';
  if (r.user && r.user.name) { userName = r.user.name; }
  newReviews.push({
    nom: userName,
    note: r.rating || 0,
    commentaire: r.snippet || '',
    iso_date: isoDate,
    review_link: r.review_link || ''
  });
}

if (reviews.length > 0) {
  var latest = reviews[0];
  staticData.lastSeenDate = latest.iso_date_of_last_edit || latest.iso_date || '';
}

if (newReviews.length === 0) {
  return [{ json: { hasNew: false, count: 0, reviews: [] } }];
}
return [{ json: { hasNew: true, count: newReviews.length, reviews: newReviews } }];
